BEGIN;

ALTER FUNCTION refs_get_source_document_detail(uuid,uuid,uuid) RENAME TO refs_get_source_document_detail_v164;

CREATE FUNCTION refs_get_source_document_detail(p_tenant uuid,p_entity uuid,p_source_document uuid)
RETURNS TABLE(source_document_id uuid,source_document_revision bigint,raw_event_id uuid,source_system text,source_module text,source_record_id text,source_version text,document_type text,document_no text,business_date date,accounting_date date,currency char(3),gross_amount numeric(22,4),status text,payload_hash text,source_line_count bigint,posted_journal_entry_ids uuid[],lines jsonb,created_at timestamptz,updated_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN
 PERFORM refs_assert_scope(p_tenant,p_entity,'GL.JE.VIEW');
 IF NOT EXISTS(SELECT 1 FROM source_document d WHERE d.tenant_id=p_tenant AND d.entity_id=p_entity AND d.source_document_id=p_source_document) THEN RAISE EXCEPTION 'Source document is absent or outside the entity' USING ERRCODE='P0002';END IF;
 RETURN QUERY SELECT d.source_document_id,d.version,d.raw_event_id,d.source_system,d.source_module,d.source_record_id,d.source_version,d.document_type,d.document_no,d.business_date,d.accounting_date,d.currency,d.gross_amount,d.status::text,d.payload_hash,
  (SELECT count(*)::bigint FROM source_document_line l WHERE l.tenant_id=p_tenant AND l.entity_id=p_entity AND l.source_document_id=d.source_document_id),
  ARRAY(SELECT DISTINCT link.journal_entry_id FROM source_link link JOIN journal_entry j ON j.tenant_id=link.tenant_id AND j.entity_id=link.entity_id AND j.journal_entry_id=link.journal_entry_id WHERE link.tenant_id=p_tenant AND link.entity_id=p_entity AND link.source_document_id=d.source_document_id AND link.journal_entry_id IS NOT NULL AND j.status='POSTED' ORDER BY link.journal_entry_id)::uuid[],
  COALESCE((SELECT jsonb_agg(jsonb_build_object('source_document_line_id',l.source_document_line_id,'source_line_id',l.source_line_id,'line_no',l.line_no,'amount',l.amount,'direction',l.direction,'party_ref',l.party_ref,'bank_account_ref',l.bank_account_ref,'project_ref',l.project_ref,'property_ref',l.property_ref,'phase_ref',l.phase_ref,'unit_ref',l.unit_ref,'loan_ref',l.loan_ref,'cost_code_ref',l.cost_code_ref,
    'provider_trace',CASE WHEN retained.wbs_final1_retained_source_row_id IS NULL THEN NULL WHEN retained.domain='PAYABLES' THEN jsonb_build_object('trace_version','WBS_PROVIDER_SOURCE_TRACE_V1','domain','PAYABLES','source_payload_hash',d.payload_hash,'disposition','RETAINED','action_flags',jsonb_build_object('can_propose_amortization',false,'can_review',false,'can_create_draft',false,'can_approve',false,'can_post',false),'invoice_no',d.document_no,'invoice_date',l.external_dimension_refs->>'signed_invoice_date','business_id',l.external_dimension_refs->>'signed_business_id','accrual',jsonb_build_object('service_period_start',l.external_dimension_refs->>'signed_service_period_start','service_period_end',l.external_dimension_refs->>'signed_service_period_end','recurring_obligation_id',l.external_dimension_refs->>'signed_recurring_obligation_id','contract_id',l.external_dimension_refs->>'signed_contract_id','charge_code',l.external_dimension_refs->>'signed_charge_code','service_frequency',l.external_dimension_refs->>'signed_service_frequency','obligation_status',l.external_dimension_refs->>'signed_obligation_status')) ELSE jsonb_build_object('trace_version','WBS_PROVIDER_SOURCE_TRACE_V1','domain','INSURANCE','source_payload_hash',d.payload_hash,'action_flags',jsonb_build_object('can_propose_amortization',false,'can_review',false,'can_create_draft',false,'can_approve',false,'can_post',false),'policy_id',regexp_replace(d.source_record_id,'^insurance:','','i'),'source_id',l.source_line_id,'pc_code',l.external_dimension_refs->>'signed_pc_code','final_premium',l.amount::text,'mapping_decision_id',CASE WHEN retained.outcome='AMORTIZATION_COVERAGE_EVIDENCE_CANDIDATE' AND COALESCE((l.external_dimension_refs->>'insurance_pc_mapping_match_count')::integer,0)=1 THEN decision.wbs_insurance_pc_company_mapping_decision_id ELSE NULL END,'mapping_decision_hash',CASE WHEN retained.outcome='AMORTIZATION_COVERAGE_EVIDENCE_CANDIDATE' AND COALESCE((l.external_dimension_refs->>'insurance_pc_mapping_match_count')::integer,0)=1 THEN decision.decision_hash ELSE NULL END,'company_mapping_hash',CASE WHEN retained.outcome='AMORTIZATION_COVERAGE_EVIDENCE_CANDIDATE' AND COALESCE((l.external_dimension_refs->>'insurance_pc_mapping_match_count')::integer,0)=1 THEN decision.company_mapping_hash ELSE NULL END,'resolved_company_code',CASE WHEN retained.outcome='AMORTIZATION_COVERAGE_EVIDENCE_CANDIDATE' AND COALESCE((l.external_dimension_refs->>'insurance_pc_mapping_match_count')::integer,0)=1 THEN decision.company_code ELSE NULL END,'match_count',CASE WHEN retained.outcome='AMORTIZATION_COVERAGE_EVIDENCE_CANDIDATE' AND decision.wbs_insurance_pc_company_mapping_decision_id IS NOT NULL AND COALESCE((l.external_dimension_refs->>'insurance_pc_mapping_match_count')::integer,0)=1 THEN 1 ELSE 0 END,'disposition',CASE WHEN retained.outcome<>'AMORTIZATION_COVERAGE_EVIDENCE_CANDIDATE' THEN 'QUARANTINED' WHEN decision.wbs_insurance_pc_company_mapping_decision_id IS NULL OR COALESCE((l.external_dimension_refs->>'insurance_pc_mapping_match_count')::integer,0)<>1 THEN 'MAPPING_REVIEW_REQUIRED' ELSE 'RESOLVED' END,'coverage_start',l.external_dimension_refs->>'signed_coverage_start','coverage_end',l.external_dimension_refs->>'signed_coverage_end','coverage_disposition',CASE WHEN retained.outcome='AMORTIZATION_COVERAGE_EVIDENCE_CANDIDATE' THEN 'POSITIVE_COVERAGE' ELSE 'EXCEPTION_REVIEW_REQUIRED' END) END
  ) ORDER BY l.line_no,l.source_document_line_id)
  FROM source_document_line l LEFT JOIN wbs_final1_retained_source_row retained ON retained.tenant_id=l.tenant_id AND retained.entity_id=l.entity_id AND retained.source_document_line_id=l.source_document_line_id LEFT JOIN wbs_final1_retained_evidence_admission admission ON admission.tenant_id=retained.tenant_id AND admission.entity_id=retained.entity_id AND admission.wbs_final1_retained_evidence_admission_id=retained.wbs_final1_retained_evidence_admission_id LEFT JOIN wbs_insurance_pc_company_mapping_decision decision ON retained.domain='INSURANCE' AND decision.tenant_id=retained.tenant_id AND decision.entity_id=retained.entity_id AND decision.wbs_insurance_pc_company_mapping_decision_id=CASE WHEN l.external_dimension_refs->>'insurance_pc_mapping_id'~'^[0-9a-f-]{36}$' THEN (l.external_dimension_refs->>'insurance_pc_mapping_id')::uuid ELSE NULL END WHERE l.tenant_id=p_tenant AND l.entity_id=p_entity AND l.source_document_id=d.source_document_id),'[]'::jsonb),d.created_at,d.updated_at
 FROM source_document d WHERE d.tenant_id=p_tenant AND d.entity_id=p_entity AND d.source_document_id=p_source_document;
END $$;

REVOKE ALL ON FUNCTION refs_get_source_document_detail(uuid,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION refs_get_source_document_detail(uuid,uuid,uuid) TO refs_app;
COMMIT;
